update public.own_thesis set bullet_1 = $t$Warrior is the basket's lowest-cost producer: all-longwall Mines 4 and 7 plus Blue Creek, shipping through Mobile. Q2 FY2026 cash cost was $92.53/t, down 9% y/y on Blue Creek mix and the 45X credit; LTM gross margin 30.5% vs 10.0% at AMR.$t$, bullet_2 = $t$Blue Creek was funded without new equity and adds 5.0M of the 13.0-14.0M short tons guided for FY2026. With that capex done, Q2 FY2026 FCF was $103.4M and net cash $87M; above the $350-400M cash target, buybacks become the lever.$t$, bullet_3 = $t$Valuation builds on the two pillars above: 16M short tons with Blue Creek ramped, at a ~$118/t margin ($213 2023 price less a $95 cost the low-cost base can hold), gives $1,843M EBITDA; at 4.5x, $158.72 per share, +73% vs $91.94.$t$, claim_1 = $t$Cash cost of sales (FOB port) stays at or below $100/t in Q3 FY2026 and through the H2 FY2026 longwall moves (Q2 FY2026: $92.53).$t$, claim_2 = $t$FY2027 guidance sets Blue Creek at 6.0M short tons or more and total at 14.5M or more, and cash passes $400M or a buyback or special dividend comes by the Q4 FY2026 report.$t$, claim_3 = $t$Quarterly cash margin per short ton keeps rising from $45.29 (Q2 FY2026) toward the ~$118 Recovery level, taking EBITDA from $440M LTM toward $1,843M.$t$, breaks_1 = $t$Cash cost above $100/t in Q3 or Q4 FY2026, or one longwall event removing 25% or more of production.$t$, breaks_2 = $t$FY2027 guidance leaves Blue Creek below 6.0M short tons, or cash exceeds $400M with no buyback or dividend by Q4 FY2026.$t$, breaks_3 = $t$Net selling price stays near $135/t through 2030 (Bear case): EBITDA about $515M and value of $45.54, below today's price.$t$ where id = '628a7d32-59b8-487b-9902-5a8dabfb84e5';
update public.thesis_summaries set headline = $t$Lowest-cost producer in the basket$t$, bullets = array[$t$All-longwall Mines 4 and 7 plus Blue Creek, shipping through Mobile.$t$, $t$Cash cost $92.53/t in Q2 FY2026, down 9% y/y.$t$, $t$LTM gross margin 30.5% vs 10.0% at AMR.$t$], confidence = 'high', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = '628a7d32-59b8-487b-9902-5a8dabfb84e5') and member_ticker = 'HCC' and slot = 1;
update public.thesis_summaries set headline = $t$Blue Creek is funded; cash now goes to holders$t$, bullets = array[$t$Funded without new equity; 5.0M of the 13.0-14.0M short tons guided for FY2026.$t$, $t$Q2 FY2026 FCF $103.4M; net cash $87M.$t$, $t$Above the $350-400M cash target, buybacks become the lever.$t$], confidence = 'high', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = '628a7d32-59b8-487b-9902-5a8dabfb84e5') and member_ticker = 'HCC' and slot = 2;
update public.thesis_summaries set headline = $t$4.5x Recovery EBITDA of $1,843M gives $158.72$t$, bullets = array[$t$16M short tons at ~$118/t: $213 (2023) price less $95 cost.$t$, $t$+73% vs $91.94; Bear case $45.54.$t$, $t$Illustrative upside, not a target.$t$], confidence = 'medium', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = '628a7d32-59b8-487b-9902-5a8dabfb84e5') and member_ticker = 'HCC' and slot = 3;
update public.own_thesis set bullet_1 = $t$Alpha is the basket's high-cost name (Met cost $103.07/t vs $118.71/t realization, Q2 FY2026), so its edge is flexibility: small mines, its own blending terminal, low-vol Kingston Wildcat tons and 3.8M domestic tons committed for 2026.$t$, bullet_2 = $t$It can wait out the trough without dilution: net cash $327M and $447.8M liquidity at Q2 FY2026, despite a fifth straight loss. Buybacks cut diluted shares from 18.9M (FY2021) to 14.6M (FY2023); about 12.7M today.$t$, bullet_3 = $t$Valuation builds on the two pillars above: 14M t from the flexible base at a ~$74/t margin ($179.40 FY2023 realization less $105 cost) gives $990M EBITDA; with net cash and 12.7M shares, 4.5x gives $377.13, +117% vs $173.82.$t$, claim_1 = $t$Met cost of coal sales at or below $103.00/t in Q4 FY2026 as Kingston Wildcat ramps, and 3.8M or more 2027 domestic tons committed at an average of at least $128.17/t.$t$, claim_2 = $t$Total liquidity stays at or above $400M at the end of Q3 and Q4 FY2026 (Q2 FY2026: $447.8M), with no equity issuance and the share count at or below 12.7M.$t$, claim_3 = $t$Met margin per ton rises from $15.64 (Q2 FY2026) toward ~$74 on about 14M t, taking EBITDA from $121M LTM toward the $990M Recovery figure.$t$, breaks_1 = $t$Met cost above $107.00/t in Q4 FY2026, or 2027 domestic commitments below 3.8M t or priced under $128.17/t.$t$, breaks_2 = $t$Liquidity below $400M at the end of Q3 or Q4 FY2026, or any equity issuance.$t$, breaks_3 = $t$Met realization stays near $120/t through 2030 (Bear case): EBITDA about $169M and value of $75.63 per share.$t$ where id = 'd6e203ec-c789-432a-9ab9-2a6c36b2f6e0';
update public.thesis_summaries set headline = $t$High cost, offset by flexibility$t$, bullets = array[$t$Met cost $103.07/t vs $118.71/t realization in Q2 FY2026.$t$, $t$Small mines, own blending terminal, low-vol Kingston Wildcat tons.$t$, $t$3.8M domestic tons committed for 2026.$t$], confidence = 'high', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = 'd6e203ec-c789-432a-9ab9-2a6c36b2f6e0') and member_ticker = 'AMR' and slot = 1;
update public.thesis_summaries set headline = $t$Net cash lets it wait without dilution$t$, bullets = array[$t$Net cash $327M; liquidity $447.8M at Q2 FY2026.$t$, $t$Fifth straight loss, carried by the balance sheet.$t$, $t$Diluted shares 18.9M (FY2021) to 14.6M (FY2023); ~12.7M today.$t$], confidence = 'high', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = 'd6e203ec-c789-432a-9ab9-2a6c36b2f6e0') and member_ticker = 'AMR' and slot = 2;
update public.thesis_summaries set headline = $t$4.5x Recovery EBITDA of $990M gives $377.13$t$, bullets = array[$t$14M t at ~$74/t: $179.40 FY2023 realization less $105 cost.$t$, $t$+117% vs $173.82; Bear case $75.63.$t$, $t$Illustrative upside, not a target.$t$], confidence = 'medium', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = 'd6e203ec-c789-432a-9ab9-2a6c36b2f6e0') and member_ticker = 'AMR' and slot = 3;
update public.own_thesis set bullet_1 = $t$CNR is the only member that is roughly half thermal: PAMC high-CV thermal, PRB and the Core Marine Terminal are 61% of Bear-case segment EBITDA, cushioning the trough, while the Leer complex (8.7M coking tons contracted for 2026) carries the met upside.$t$, bullet_2 = $t$CNR pays out: $360M returned since February 2025, $68M in Q2 FY2026, under a ~75%-of-FCF framework, while keeping the balance sheet about net-debt neutral (net cash $26M, LTM FCF yield 5.7%).$t$, bullet_3 = $t$Valuation builds on the two pillars above: $4.27B revenue at 41.7%, CNR's own best LTM margin of the last 3 years (set by pre-merger CONSOL), gives $1,780M EBITDA; with net cash held, 4.5x gives $162.02 per share, +77% vs $91.36.$t$, claim_1 = $t$Met cash cost stays at or below $91/t in Q3 and Q4 FY2026 (Q2 FY2026: $85.65), and FY2027 guidance sets coking sales midpoint at 8.5M t or more and cash cost at $90/t or less.$t$, claim_2 = $t$Shareholder returns of at least $100M in Q3 FY2026 (Q2 FY2026: $68M), with net debt held at or below zero.$t$, claim_3 = $t$EBITDA margin rises from 16.9% LTM (Q2 FY2026) toward ~41.7% on revenue near $4.27B, taking EBITDA from $723M LTM, which includes $125M of insurance, toward $1,780M.$t$, breaks_1 = $t$Met cash cost above $91/t in Q3 or Q4 FY2026, or another Leer or Leer South longwall event.$t$, breaks_2 = $t$Q3 FY2026 returns below the $68M of Q2 FY2026, or net debt turning positive to fund returns.$t$, breaks_3 = $t$Met and thermal margins stay at Q2 FY2026 levels (Bear case): EBITDA about $623M and value of $57.05 per share.$t$ where id = 'bca79e2f-a68a-45a1-a61d-d850b18fb5ef';
update public.thesis_summaries set headline = $t$Half thermal: a cushion in the trough$t$, bullets = array[$t$PAMC, PRB and Core Marine Terminal: 61% of Bear-case segment EBITDA.$t$, $t$Leer complex: 8.7M coking tons contracted for 2026.$t$, $t$Loses less than the pure met names in a bear case.$t$], confidence = 'high', model = 'Claude', is_stale = false, updated_at = now() where position_id = (select position_id from public.own_thesis where id = 'bca79e2f-a68a-45a1-a61d-d850b18fb5ef') and member_ticker = 'CNR' and slot = 1;
